    private void setCellBold(org.odftoolkit.odfdom.doc.table.OdfTableCell cell) {
        cell.getOdfElement().setProperty(OdfTextProperties.FontWeight, "bold");
    }

    private void setCellBackgroundColor(org.odftoolkit.odfdom.doc.table.OdfTableCell cell, String color) {
        cell.getOdfElement().setProperty(OdfTableCellProperties.BackgroundColor, color);
    }

    private void appendKV(org.odftoolkit.odfdom.doc.table.OdfTable table, String key, double value) {
        org.odftoolkit.odfdom.doc.table.OdfTableRow row = table.appendRow();
        row.getCellByIndex(0).setStringValue(key);
        row.getCellByIndex(1).setDoubleValue(value);
    }

    private void appendKV(org.odftoolkit.odfdom.doc.table.OdfTable table, String key, String value) {
        org.odftoolkit.odfdom.doc.table.OdfTableRow row = table.appendRow();
        row.getCellByIndex(0).setStringValue(key);
        row.getCellByIndex(1).setStringValue(value);
    }

    private void appendKV(org.odftoolkit.odfdom.doc.table.OdfTable table, String key, int value) {
        org.odftoolkit.odfdom.doc.table.OdfTableRow row = table.appendRow();
        row.getCellByIndex(0).setStringValue(key);
        row.getCellByIndex(1).setDoubleValue((double) value);
    }

    /**
     * Auto-fit column widths. Uses setUseOptimalWidth(true) to bypass the
     * buggy setWidth() in odfdom 0.10.0 (locale comma NumberFormatException).
     */
    private void autoFitColumnWidths(org.odftoolkit.odfdom.doc.table.OdfTable table) {
        int colCount = table.getColumnCount();
        if (colCount == 0) {
            return;
        }
        for (int c = 0; c < colCount; c++) {
            org.odftoolkit.odfdom.doc.table.OdfTableColumn col = table.getColumnByIndex(c);
            if (col != null) {
                col.setUseOptimalWidth(true);
            }
        }
    }

